{
  "name": "prompt-cache-control",
  "version": "0.1.0",
  "description": "Prompt-cache meter above the Claude Code prompt: how many tokens each request read from, wrote to and sent past the cache, a live countdown to the cache's expiry, and what to do about it (keep going, compact or clear). The TTL follows Claude Code's own rules for your account (1 hour on a Claude subscription, 5 minutes on an API key, cloud provider or usage credits, plus the TTL variables and setting) and corrects itself from request timing. When Claude Code will compact an idle conversation by itself, it counts down to that too. /cache opens a per-turn table.",
  "author": {
    "name": "claude-code-templates",
    "url": "https://www.aitmpl.com"
  },
  "repository": "https://github.com/davila7/claude-code-templates",
  "license": "MIT",
  "keywords": [
    "mod",
    "function-hooks",
    "observability",
    "prompt-caching",
    "cost"
  ],
  "userConfig": {
    "ttl": {
      "type": "string",
      "title": "Cache lifetime",
      "description": "How long the cache lives after a request: auto follows Claude Code's own rules (FORCE_PROMPT_CACHING_5M, CLAUDE_CODE_PROMPT_CACHE_TTL, the promptCacheTtl setting, ENABLE_PROMPT_CACHING_1H, then 1 hour on a Claude subscription and 5 minutes on an API key, cloud provider or usage credits) and corrects itself from request timing; 5m or 1h pins it",
      "default": "auto",
      "options": [
        "auto",
        "5m",
        "1h"
      ]
    },
    "warnSeconds": {
      "type": "number",
      "title": "Warn before expiry (s)",
      "description": "Seconds left on the countdown at which the band turns yellow and a toast reminds you the cache is about to lapse",
      "default": 60
    },
    "compactAtTokens": {
      "type": "number",
      "title": "Large context (tokens)",
      "description": "From this prompt size up, an expired cache suggests /compact (or /clear) before you pay to write the whole prefix again",
      "default": 100000
    },
    "band": {
      "type": "boolean",
      "title": "Band above the prompt",
      "description": "Show the meter as a row above the prompt",
      "default": true
    },
    "status": {
      "type": "boolean",
      "title": "Status line entry",
      "description": "Also pin a short entry (hit rate and countdown) under the prompt",
      "default": false
    },
    "toast": {
      "type": "boolean",
      "title": "Toast near expiry",
      "description": "Toasts as the cache lapses: at the warning threshold, then at 10, 3, 2 and 1 seconds, once per cache entry each (only for prompts of 20k tokens or more)",
      "default": true
    },
    "idleCompact": {
      "type": "boolean",
      "title": "Idle compaction",
      "description": "When Claude Code will compact a large conversation by itself before its 1-hour cache lapses (Claude Code 2.1.290+), count down to that moment in the band and say when it happened",
      "default": true
    }
  }
}

